<?php
/**
 * WHMCS Iugu Credit Card Callback & Webhook Endpoint (`modules/gateways/callback/iugucc.php`)
 *
 * Dual-Mode Handler:
 * 1. Synchronous Checkout Return (`action=checkout`):
 *    Receives the single-use `iugu_token` generated by `Iugu.js` in the browser,
 *    verifies the HMAC invoice signature, executes `POST /v1/charge`, calls
 *    `addInvoicePayment()` upon approval (triggering WHMCS service provisioning),
 *    and returns JSON status to the client checkout UI.
 *
 * 2. Asynchronous Iugu Webhook (`event=invoice.status_changed`, etc.):
 *    Receives webhook notifications from Iugu, verifies authenticity via
 *    `GET /v1/invoices/{id}` on the Iugu API, and idempotently marks the WHMCS
 *    invoice as Paid (`addInvoicePayment`) if not already recorded.
 *
 * @package    WHMCS\Module\Gateway\IuguCC
 * @target     WHMCS 8.13.7 | PHP 8.1 / 8.2
 */

declare(strict_types=1);

require_once __DIR__ . '/../../../init.php';
require_once __DIR__ . '/../../../includes/gatewayfunctions.php';
require_once __DIR__ . '/../../../includes/invoicefunctions.php';
require_once __DIR__ . '/../iugucc/autoload.php';

use WHMCS\Database\Capsule;
use WHMCS\Module\Gateway\IuguCC\ChargeProcessor;
use WHMCS\Module\Gateway\IuguCC\Config;
use WHMCS\Module\Gateway\IuguCC\IuguHttpClient;
use WHMCS\Module\Gateway\IuguCC\WebhookHandler;

$gatewayModuleName = Config::GATEWAY_NAME;
$gatewayParams = getGatewayVariables($gatewayModuleName);

if (empty($gatewayParams['type'])) {
    http_response_code(503);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['success' => false, 'message' => 'Gateway module iugucc is not active in WHMCS.']);
    exit;
}

$config = new Config($gatewayParams);

if (!$config->isConfigured()) {
    // Missing Account ID / API token, or Sandbox Mode without the Iugu TEST token. 503 makes Iugu retry
    // webhooks later and gives the checkout UI a clear, non-card-related message.
    logTransaction(
        $gatewayModuleName,
        ['sandbox_mode' => $config->isSandbox(), 'sandbox_token_missing' => $config->isSandboxTokenMissing()],
        'Gateway Not Configured'
    );
    http_response_code(503);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode([
        'success' => false,
        'lr_code' => 'NOT_CONFIGURED',
        'message' => $config->isSandboxTokenMissing()
            ? 'Modo Sandbox ativo sem Token de API de Teste da Iugu. Configure o token de teste no gateway.'
            : 'Credenciais da Iugu pendentes de configuração no WHMCS.',
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

$httpClient = new IuguHttpClient($config->getActiveApiToken());

// Parse incoming request (supports application/json and application/x-www-form-urlencoded)
$rawInput = (string) file_get_contents('php://input');
$jsonInput = [];
if ($rawInput !== '' && str_starts_with(trim($rawInput), '{')) {
    $decoded = json_decode($rawInput, true);
    if (is_array($decoded)) {
        $jsonInput = $decoded;
    }
}
$requestData = array_merge($_GET, $_POST, $jsonInput);

// Build standard WHMCS callback bridges
$whmcsCallbacks = [
    'logTransaction' => static function (string $gateway, mixed $data, string $status): void {
        logTransaction($gateway, $data, $status);
    },
    'checkCbInvoiceID' => static function (int $invoiceId, string $gateway): void {
        checkCbInvoiceID($invoiceId, $gateway);
    },
    'checkCbTransID' => static function (string $transactionId): void {
        checkCbTransID($transactionId);
    },
    'addInvoicePayment' => static function (
        int $invoiceId,
        string $transactionId,
        float $amount,
        float $fee,
        string $gateway
    ): void {
        addInvoicePayment($invoiceId, $transactionId, $amount, $fee, $gateway);
    },
    'isInvoicePaid' => static function (int|string $invoiceId): bool {
        if (!class_exists(Capsule::class)) {
            return false;
        }
        $status = Capsule::table('tblinvoices')
            ->where('id', (int) $invoiceId)
            ->value('status');
        return is_string($status) && strtolower($status) === 'paid';
    },
    'isTransactionRecorded' => static function (string $transactionId): bool {
        if (!class_exists(Capsule::class) || $transactionId === '') {
            return false;
        }
        return Capsule::table('tblaccounts')
            ->where('transid', $transactionId)
            ->exists();
    },
];

$action = strtolower(trim((string) ($requestData['action'] ?? '')));

// ============================================================================
// MODE 1: Synchronous Client-Side Tokenized Checkout Submission
// ============================================================================
if ($action === 'checkout' || isset($requestData['iugu_token'])) {
    header('Content-Type: application/json; charset=utf-8');

    $invoiceId = (int) ($requestData['invoice_id'] ?? 0);
    if ($invoiceId <= 0) {
        http_response_code(400);
        echo json_encode(['success' => false, 'message' => 'Fatura inválida.']);
        exit;
    }

    // Verify invoice exists in WHMCS and load authoritative balance & client details
    checkCbInvoiceID($invoiceId, $gatewayParams['name']);

    $invoiceRow = class_exists(Capsule::class)
        ? Capsule::table('tblinvoices')->where('id', $invoiceId)->first()
        : null;

    if ($invoiceRow === null) {
        http_response_code(404);
        echo json_encode(['success' => false, 'message' => 'Fatura não encontrada no WHMCS.']);
        exit;
    }

    // Only invoices that are still open may be charged. A checkout signature captured while the invoice
    // was Unpaid must not be usable after it is Cancelled, Refunded, sent to Collections, back to Draft or
    // Payment Pending: the card would be debited and WHMCS would not settle the invoice.
    // (Paid invoices fall through to ChargeProcessor, which answers "already paid" without charging.)
    $invoiceStatus = strtolower(trim((string) ($invoiceRow->status ?? '')));
    if ($invoiceStatus !== 'unpaid' && $invoiceStatus !== 'paid') {
        logTransaction(
            $gatewayModuleName,
            ['whmcs_invoice_id' => $invoiceId, 'invoice_status' => (string) ($invoiceRow->status ?? '')],
            'Checkout Blocked (Invoice Not Payable)'
        );
        http_response_code(409);
        echo json_encode([
            'success' => false,
            'invoice_id' => (string) $invoiceId,
            'transaction_id' => '',
            'lr_code' => 'INVOICE_NOT_PAYABLE',
            'message' => $config->isEnglish()
                ? 'This invoice is not open for payment. Please reload the invoice page.'
                : 'Esta fatura não está em aberto para pagamento. Recarregue a página da fatura.',
            'redirect_url' => null,
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        exit;
    }

    $clientId = (int) ($invoiceRow->userid ?? 0);
    $invoiceTotal = (string) ($invoiceRow->total ?? '0.00');
    $providedSignature = trim((string) ($requestData['signature'] ?? ''));

    // Compute remaining balance in case the invoice has partial credit or prior partial payments
    $paidSum = 0.0;
    if (class_exists(Capsule::class)) {
        $paidIn = (float) Capsule::table('tblaccounts')->where('invoiceid', $invoiceId)->sum('amountin');
        $paidOut = (float) Capsule::table('tblaccounts')->where('invoiceid', $invoiceId)->sum('amountout');
        $paidSum = max(0.0, $paidIn - $paidOut);
    }
    $calculatedBalance = number_format(max(0.0, ((float) $invoiceTotal) - $paidSum), 2, '.', '');

    // Verify HMAC-SHA256 checkout signature against authoritative balance or total
    $verifiedAmount = null;
    if ($config->verifyCheckoutSignature($invoiceId, $clientId, $calculatedBalance, $providedSignature)) {
        $verifiedAmount = (float) $calculatedBalance;
    } elseif ($config->verifyCheckoutSignature($invoiceId, $clientId, $invoiceTotal, $providedSignature)) {
        $verifiedAmount = (float) $invoiceTotal;
    }

    if ($verifiedAmount === null) {
        http_response_code(403);
        echo json_encode([
            'success' => false,
            'message' => 'Assinatura de segurança da fatura inválida ou expirada. Recarregue a página da fatura.',
        ]);
        exit;
    }

    // Load client record
    $clientRow = class_exists(Capsule::class)
        ? (array) Capsule::table('tblclients')->where('id', $clientId)->first()
        : [];

    $processor = new ChargeProcessor($config, $httpClient);
    $result = $processor->processCharge(
        $requestData,
        $invoiceId,
        $verifiedAmount,
        $clientRow,
        $whmcsCallbacks
    );

    $systemUrl = rtrim((string) ($gatewayParams['systemurl'] ?? ''), '/');
    $redirectUrl = $systemUrl . '/viewinvoice.php?id=' . $invoiceId . '&paymentsuccess=true';

    http_response_code($result['success'] ? 200 : 422);
    echo json_encode([
        'success' => $result['success'],
        'invoice_id' => $result['invoice_id'],
        'transaction_id' => $result['transaction_id'],
        'lr_code' => $result['lr_code'],
        'message' => $result['message'],
        'redirect_url' => $result['success'] ? $redirectUrl : null,
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

// ============================================================================
// MODE 2: Asynchronous Iugu Webhook Notification
// ============================================================================
$requestHeaders = function_exists('getallheaders') ? (array) getallheaders() : [];
$webhookHandler = new WebhookHandler($config, $httpClient);
$webhookResult = $webhookHandler->handle($requestData, $requestHeaders, $whmcsCallbacks);

http_response_code($webhookResult['http_code']);
header('Content-Type: application/json; charset=utf-8');
echo json_encode($webhookResult, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
exit;
